<template>
  <div class="forgot-page">
    <div class="forgot-container">
      <el-card class="forgot-card" shadow="always">
        <template #header>
          <div class="card-header">
            <h2 class="header-font">忘记密码</h2>
            <p class="subtitle content-font">通过邮箱验证码重置密码</p>
          </div>
        </template>

        <el-form
          ref="formRef"
          :model="form"
          :rules="rules"
          label-width="0"
          @submit.prevent="handleSubmit"
        >
          <el-form-item prop="email">
            <el-input
              v-model="form.email"
              placeholder="注册邮箱"
              size="large"
              :prefix-icon="Message"
            />
          </el-form-item>
          <p v-if="maskedEmail" class="email-hint">验证码将发送至 {{ maskedEmail }}</p>

          <el-form-item prop="email_code">
            <div class="email-code-row">
              <el-input
                v-model="form.email_code"
                placeholder="邮箱验证码（4位）"
                size="large"
                maxlength="4"
                class="email-code-input"
              />
              <el-button
                type="primary"
                size="large"
                :disabled="countdown > 0 || !form.email"
                :loading="sendingCode"
                class="send-code-btn"
                @click="handleSendCode"
              >
                {{ countdown > 0 ? `${countdown}s 后重试` : '获取验证码' }}
              </el-button>
            </div>
          </el-form-item>

          <el-form-item prop="new_password">
            <el-input
              v-model="form.new_password"
              type="password"
              placeholder="新密码（8-32位，含字母与数字）"
              size="large"
              :prefix-icon="Lock"
              show-password
            />
          </el-form-item>

          <el-form-item prop="confirm_password">
            <el-input
              v-model="form.confirm_password"
              type="password"
              placeholder="确认新密码"
              size="large"
              :prefix-icon="Lock"
              show-password
              @keyup.enter="handleSubmit"
            />
          </el-form-item>

          <el-form-item>
            <el-button
              type="primary"
              size="large"
              :loading="loading"
              class="submit-button"
              @click="handleSubmit"
            >
              重置密码
            </el-button>
          </el-form-item>

          <el-form-item>
            <el-button size="large" class="back-button" @click="router.push('/login')">
              返回登录
            </el-button>
          </el-form-item>
        </el-form>
      </el-card>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, reactive, onUnmounted, computed } from 'vue'
import { useRouter } from 'vue-router'
import * as authApi from '@/api/auth'
import { maskEmail } from '@/utils/format'
import { Message, Lock } from '@element-plus/icons-vue'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { validatePasswordStrength } from '@/utils/validation'

const router = useRouter()
const formRef = ref<FormInstance>()
const loading = ref(false)
const sendingCode = ref(false)
const countdown = ref(0)
let countdownTimer: ReturnType<typeof setInterval> | null = null

const form = reactive({
  email: '',
  email_code: '',
  new_password: '',
  confirm_password: '',
})

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const maskedEmail = computed(() =>
  form.email && emailRegex.test(form.email) ? maskEmail(form.email) : ''
)

function validateConfirmPassword(_rule: unknown, value: string, callback: (error?: Error) => void) {
  if (value !== form.new_password) {
    callback(new Error('两次输入的密码不一致'))
  } else {
    callback()
  }
}

const validateNewPassword = (_rule: unknown, value: string, callback: (error?: Error) => void) => {
  const msg = validatePasswordStrength(value)
  if (msg) callback(new Error(msg))
  else callback()
}

const rules: FormRules = {
  email: [
    { required: true, message: '请输入注册邮箱', trigger: 'blur' },
    { type: 'email', message: '请输入正确的邮箱格式', trigger: 'blur' },
  ],
  email_code: [
    { required: true, message: '请输入邮箱验证码', trigger: 'blur' },
    { len: 4, message: '验证码为 4 位数字', trigger: 'blur' },
    { pattern: /^\d{4}$/, message: '验证码为 4 位数字', trigger: 'blur' },
  ],
  new_password: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { validator: validateNewPassword, trigger: 'blur' },
  ],
  confirm_password: [
    { required: true, message: '请确认新密码', trigger: 'blur' },
    { validator: validateConfirmPassword, trigger: 'blur' },
  ],
}

async function handleSendCode() {
  if (!form.email || countdown.value > 0) return
  const emailRule = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!emailRule.test(form.email)) {
    ElMessage.warning('请先输入正确邮箱')
    return
  }
  sendingCode.value = true
  try {
    await authApi.sendEmailCode(form.email)
    ElMessage.success(`验证码已发送至 ${maskEmail(form.email)}，请查收`)
    countdown.value = 60
    countdownTimer = setInterval(() => {
      countdown.value--
      if (countdown.value <= 0 && countdownTimer) {
        clearInterval(countdownTimer)
        countdownTimer = null
      }
    }, 1000)
  } catch (err: unknown) {
    ElMessage.error((err as Error).message || '发送失败')
  } finally {
    sendingCode.value = false
  }
}

onUnmounted(() => {
  if (countdownTimer) clearInterval(countdownTimer)
})

async function handleSubmit() {
  if (!formRef.value) return
  await formRef.value.validate(async (valid) => {
    if (!valid) return
    loading.value = true
    try {
      await authApi.resetPassword({
        email: form.email,
        email_code: form.email_code,
        new_password: form.new_password,
      })
      ElMessage.success('密码已重置，请登录')
      router.push('/login')
    } catch (err: unknown) {
      ElMessage.error((err as Error).message || '重置失败')
    } finally {
      loading.value = false
    }
  })
}
</script>

